<?php require_once __DIR__.'/../core.php'; require_once __DIR__.'/auth.php'; ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prospects</title><link rel="stylesheet" href="/assets/css/style.css?v=110"></head><body><div class="admin-layout"><?php include __DIR__.'/sidebar.php'; ?><main class="admin-main"><?php $items=data_list('prospects'); if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['bulk'])){foreach(preg_split('/\r\n|\n|\r/',$_POST['bulk']) as $line){$line=trim($line);if(!$line)continue;$p=array_map('trim',explode(',',$line));$items[]=['id'=>time().rand(10,99),'name'=>$p[0]??'Prospect','phone'=>$p[1]??'','email'=>$p[2]??'','whatsapp'=>$p[3]??($p[1]??''),'source'=>'import','date'=>now()];}}else{$items[]=['id'=>time(),'name'=>$_POST['name'],'phone'=>$_POST['phone'],'email'=>$_POST['email'],'whatsapp'=>$_POST['whatsapp'],'source'=>$_POST['source'],'date'=>now()];}data_save('prospects',$items);header('Location:/admin/prospects.php');exit;} ?><h1>Prospects</h1><form class="card" method="post"><div class="form-grid"><label>Nom<input name="name"></label><label>Téléphone<input name="phone"></label><label>Email<input name="email"></label><label>WhatsApp<input name="whatsapp"></label><label>Source<input name="source" value="manuel"></label></div><button class="btn btn-primary">Ajouter</button></form><div class="card"><h3>Importer une liste</h3><form method="post"><textarea name="bulk" rows="6" placeholder="Nom, téléphone, email, whatsapp"></textarea><button class="btn btn-gold">Importer</button></form></div><table class="table"><tr><th>Nom</th><th>Téléphone</th><th>Email</th><th>WhatsApp</th></tr><?php foreach(array_reverse($items) as $p): ?><tr><td><?=e($p['name'])?></td><td><?=e($p['phone'])?></td><td><?=e($p['email'])?></td><td><?=e($p['whatsapp'])?></td></tr><?php endforeach; ?></table></main></div><script>
(function(){const saved=localStorage.getItem('geah_theme')||'dark';if(saved==='light')document.body.classList.add('light-mode');function ready(){const btn=document.createElement('button');btn.className='theme-toggle';function label(){btn.textContent=document.body.classList.contains('light-mode')?'🌙 Mode sombre':'☀️ Mode clair'}btn.onclick=function(){document.body.classList.toggle('light-mode');localStorage.setItem('geah_theme',document.body.classList.contains('light-mode')?'light':'dark');label()};label();document.body.appendChild(btn)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();})();
</script></body></html>